package com.ricozknow.enterprise.metering; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*; @RestController @RequestMapping("/api/v1/admin/usage") @RequiredArgsConstructor public class UsageController {private final UsageMeteringService service; @GetMapping @PreAuthorize("hasRole('ADMIN')") public List<UsageMeter> usage(){return service.current();} @GetMapping("/ai-costs") @PreAuthorize("hasRole('ADMIN')") public List<AiCostEvent> costs(@RequestParam Instant from,@RequestParam Instant to){return service.costs(from,to);} }
